<template><section class="rag-evidence-panel"><p v-if="error" class="alert danger">检索证据读取失败：{{ error }}</p><AsyncState v-else-if="!items.length" kind="empty" message="此 Workflow Run 没有 Agent RAG 证据。" /><article v-for="item in items" :key="`${item.stepKey}-${item.agentRunUuid}`"><header><div><strong>{{ item.stepKey }}</strong><small>{{ item.agentRunUuid }}</small></div><span :class="['status-pill', `tone-${tone(item)}`]">{{ state(item).label }}</span></header><p v-if="state(item).mock" class="alert danger">Mock 检索/模型证据，仅用于测试，不计入真实指标。</p><dl><div><dt>上下文预算</dt><dd>{{ item.contextBudget ?? '未报告' }}</dd></div><div><dt>检索版本</dt><dd>{{ item.retrievalVersion || '—' }}</dd></div><div><dt>切块版本</dt><dd>{{ item.chunkingVersion || '—' }}</dd></div><div><dt>Embedding</dt><dd>{{ item.embeddingModel || '—' }}</dd></div></dl><div v-if="item.references?.length" class="reference-list"><div v-for="ref in item.references.map(safeReference)" :key="ref.chunkUuid"><strong>#{{ ref.rank }} · {{ ref.score }}</strong><code>{{ ref.documentUuid }} v{{ ref.documentVersion }}</code><code>{{ ref.chunkUuid }}</code></div></div><p v-else>{{ state(item).kind === 'failed' ? '后端报告检索失败。' : state(item).kind === 'off' ? '此 Agent Run 明确关闭 RAG。' : '检索已执行但没有候选引用。' }}</p></article></section></template>
<script setup>import AsyncState from "../../shared/ui/AsyncState.vue";import { ragEvidenceState,safeReference } from "./ragEvidence.js";defineProps({items:{type:Array,default:()=>[]},error:String});const state=item=>ragEvidenceState(item);const tone=item=>({on:"success",failed:"danger",off:"neutral","no-candidates":"warning"})[state(item).kind];</script>
